        async function publishVideoFromSlot(campToken, slotIdx, btnElem) {
            const selectElem = document.getElementById(`slot-video-select-${slotIdx}`);
            const filename = selectElem ? selectElem.value : "";
            
            if (!filename) {
                alert("Seleziona prima un file video MP4 da pubblicare per questo slot!");
                return;
            }

            const captionElem = document.getElementById(`slot-caption-${slotIdx}`);
            const captionText = captionElem ? captionElem.innerText : "";

            const origHtml = btnElem.innerHTML;
            btnElem.innerHTML = '⏳ Caricamento...';
            btnElem.disabled = true;

            try {
                const res = await fetch('/api/tiktok/upload', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        filename: filename,
                        title: captionText || filename,
                        cover_time_ms: 1000,
                        campaign_id: campToken
                    })
                });
                const data = await res.json();
                if (data.status === 'success' || data.id) {
                    alert(`✅ Video "${filename}" inviato con successo a TikTok per la campagna!`);
                    
                    // Aggiungi a publishedContent locale
                    publishedContent.push({
                        campaign_id: campToken,
                        filename: filename,
                        timestamp: new Date().toISOString().replace('T', ' ').substr(0, 19),
                        title: captionText
                    });

                    renderCampaignDetailContent(campToken);
                } else {
                    alert("Errore upload TikTok: " + (data.error || "Errore sconosciuto"));
                }
            } catch(e) {
                alert("Errore comunicazione server: " + e.message);
            } finally {
                btnElem.innerHTML = origHtml;
                btnElem.disabled = false;
            }
        }

